        /// Send an email Sends from the connected mailbox and returns the stored sent copy.  The message is mirrored into the inbox (&#x60;message.sent&#x60; fires once) and counted against the mailbox&#39;s daily cap. The cap is reported in the &#x60;X-Zernio-Send-Limit&#x60;, &#x60;X-Zernio-Send-Remaining&#x60; and &#x60;X-Zernio-Send-Reset&#x60; response headers.  ### Sending limits  These mailboxes are for one-to-one mail, not bulk sends. Protection on every mailbox:  - Daily cap: Microsoft 1,000; Google Workspace 500; Gmail consumer 200. Reaching it answers 429 &#x60;email_send_cap_reached&#x60; with &#x60;details.cap&#x60;. - The same body reaching more than 50 distinct recipients within an hour pauses the mailbox with an escalating cooldown (429 &#x60;rate_limited&#x60;, &#x60;account.rate_limited&#x60; webhook).  ### Scheduling  With &#x60;scheduledFor&#x60; the request answers 202 with a &#x60;ScheduledEmail&#x60; instead of sending. The account and payment method are checked now; the caps, cooldowns and the send itself run at &#x60;scheduledFor&#x60;. A send that fails then fires &#x60;email.send_failed&#x60;. List, read and cancel scheduled sends under &#x60;/v1/email/messages/scheduled&#x60;.  ### Tracking  - &#x60;trackOpens&#x60; adds a 1x1 image to the html and fires &#x60;email.opened&#x60;. - &#x60;trackLinks&#x60; rewrites every http(s) link in the html through a Zernio redirect and fires &#x60;email.link_clicked&#x60;. - &#x60;trackReplies&#x60; fires &#x60;email.thread_replied&#x60; when someone else writes in the thread.  Tracking costs nothing extra. Opens are approximate: image proxies prefetch and image blocking hides them.  ### Other errors  - 402: Gmail sends need a payment method on the workspace. Reading, calendar and files do not. - 400: &#x60;holdAsDraft&#x60; without &#x60;scheduledFor&#x60;; &#x60;trackOpens&#x60; or &#x60;trackLinks&#x60; without &#x60;html&#x60;; &#x60;scheduledFor&#x60; outside 1 minute to 30 days. 
